import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
  Vector3,
} from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load texture from config.imageUrl (pre-cached)
  const map = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/feature-card.png');

  // Geometry dimensions derived from atlas source rect (512x320) => aspect ratio 1.6
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Material with basic texture, no lighting needed per visual spec
  const material = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    needsUpdate: true,
  });
  // Assign texture via TSL node
  material.colorNode = texture(map);

  const mesh = new Mesh(geometry, material);

  // Set scene placement from config (position, rotation, scale)
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  }
  if (config.sceneRotation) {
    mesh.rotation.set(
      config.sceneRotation.x ?? 0,
      config.sceneRotation.y ?? 0,
      config.sceneRotation.z ?? 0
    );
  }
  if (config.sceneScale) {
    mesh.scale.set(
      config.sceneScale.x ?? 1,
      config.sceneScale.y ?? 1,
      config.sceneScale.z ?? 1
    );
  }

  // No event handlers needed for static card
  mesh.userData.handlers = {};

  // Cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // map is cached, not owned, so skip dispose
  };

  return mesh;
}
